const chatInput = $('TrialChatTrigger').first().json;
const addressRow = $('FetchActiveAddressForTrial').first().json;
const alamat = (addressRow && addressRow['Alamat']) || 'belum diisi';
return [{ json: {
  menu,
  alamat,
  chatInput: chatInput.chatInput,
  sessionId: chatInput.sessionId
} }];

