let out;
try {
  let raw = $json.output || $json.text || '';
  raw = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  out = JSON.parse(raw);
} catch (e) {
  return [{ json: { output: '⚠️ Gagal parse JSON dari AI. Raw output:\n' + ($json.output || $json.text) } }];
}
const debug = {
  status: out.status,
  kirim_foto_menu: out.kirim_foto_menu,
  order_detail: out.order_detail
};
const display = out.reply + 
  '\n\n---\n\U0001F9EA DEBUG (cuma keliatan di sini, bukan di WA asli):\n' +
  JSON.stringify(debug, null, 2);
return [{ json: { output: display } }];
